import { Match as M, Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as CheckboxGroup from "../../../foldkit/ui/checkbox-group";

// MODEL

export const AppleValue = S.Union([
  S.Literal("fuji-apple"),
  S.Literal("gala-apple"),
  S.Literal("granny-smith-apple"),
]);
export type AppleValue = typeof AppleValue.Type;

export const Model = S.Struct({
  selectedApples: S.Array(AppleValue),
});

export type Model = typeof Model.Type;

const appleValues: readonly AppleValue[] = [
  "fuji-apple",
  "gala-apple",
  "granny-smith-apple",
];

// MESSAGE

export const ToggledApple = m("ToggledApple", { value: AppleValue });
export const ToggledAllApples = m("ToggledAllApples");

export const Message = S.Union([ToggledApple, ToggledAllApples]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{ selectedApples: ["fuji-apple"] }, []];

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      ToggledApple: ({ value }) => [
        evo(model, {
          selectedApples: (selectedApples) =>
            CheckboxGroup.toggleValue(selectedApples, value),
        }),
        [],
      ],
      ToggledAllApples: () => [
        evo(model, {
          selectedApples: (selectedApples) =>
            CheckboxGroup.parentState(selectedApples, appleValues) === "checked"
              ? []
              : appleValues,
        }),
        [],
      ],
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>(
  (model): Html =>
    CheckboxGroup.groupView<Message>({
      label: "Apples",
      labelId: "checkbox-group-apples-label",
      name: "apple",
      children: [
        CheckboxGroup.parentItemView<Message>({
          selectedValues: model.selectedApples,
          allValues: appleValues,
          label: "All apples",
          onValueChange: ToggledAllApples(),
          classes: "mb-1",
        }),
        CheckboxGroup.itemView<Message>({
          value: "fuji-apple",
          selectedValues: model.selectedApples,
          label: "Fuji",
          onValueChange: ToggledApple({ value: "fuji-apple" }),
        }),
        CheckboxGroup.itemView<Message>({
          value: "gala-apple",
          selectedValues: model.selectedApples,
          label: "Gala",
          onValueChange: ToggledApple({ value: "gala-apple" }),
        }),
        CheckboxGroup.itemView<Message>({
          value: "granny-smith-apple",
          selectedValues: model.selectedApples,
          label: "Granny Smith",
          onValueChange: ToggledApple({ value: "granny-smith-apple" }),
        }),
      ],
    })
);

import { Runtime } from "foldkit";

import { Model, init, update, view } from "./main";

const program = Runtime.makeProgram({
  Model,
  init,
  update,
  view: (model) => ({
    title: "Checkbox Group Basic",
    body: view(model),
  }),
  container: document.querySelector("#root"),
});

Runtime.run(program);

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as CheckboxGroupBasicExample from "./main";

describe("Checkbox Group Basic example", () => {
  test("matches the Base UI checkbox group hero behavior", () => {
    Scene.scene(
      {
        update: CheckboxGroupBasicExample.update,
        view: CheckboxGroupBasicExample.view,
      },
      Scene.with(CheckboxGroupBasicExample.init()[0]),
      Scene.expect(Scene.role("group", { name: "Apples" })).toExist(),
      Scene.expect(Scene.role("checkbox", { name: "Fuji" })).toHaveAttr(
        "aria-checked",
        "true"
      ),
      Scene.click(Scene.text("Gala")),
      Scene.expect(Scene.role("checkbox", { name: "Gala" })).toHaveAttr(
        "aria-checked",
        "true"
      ),
      Scene.expect(Scene.role("checkbox", { name: "All apples" })).toHaveAttr(
        "aria-checked",
        "mixed"
      ),
      Scene.click(Scene.text("All apples")),
      Scene.expect(Scene.role("checkbox", { name: "Granny Smith" })).toHaveAttr(
        "aria-checked",
        "true"
      )
    );
  });
});
